'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isObject = require( '@stdlib/assert/is-object' );
var array = require( '@stdlib/ndarray/array' );
var QuantitativeChart = require( '@stdlib/plot/charts/base/quantitative' );
var LineChart = require( './../lib/main.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof LineChart, 'function', 'main export is a function' );
	t.end();
});

tape( 'the export is a class constructor', function test( t ) {
	var chart = new LineChart();
	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.end();
});

tape( 'the constructor has a `name` property', function test( t ) {
	t.strictEqual( LineChart.name, 'LineChart', 'returns expected value' );
	t.end();
});

tape( 'instances inherit from the quantitative chart constructor', function test( t ) {
	var chart = new LineChart();
	t.strictEqual( chart instanceof QuantitativeChart, true, 'returns expected value' );
	t.end();
});

tape( 'the constructor defines scale accessors on its own prototype (not on the parent prototype)', function test( t ) {
	var props;
	var i;

	props = [
		'colorScale',
		'lineOpacityScale',
		'lineStyleScale',
		'lineSymbolScale',
		'lineWidthScale'
	];
	for ( i = 0; i < props.length; i++ ) {
		t.strictEqual( hasOwnProp( LineChart.prototype, props[ i ] ), true, 'has own property `'+props[ i ]+'`' );
		t.strictEqual( hasOwnProp( QuantitativeChart.prototype, props[ i ] ), false, 'parent prototype does not have property `'+props[ i ]+'`' );
	}
	t.end();
});

tape( 'the constructor does not require the `new` keyword (no arguments)', function test( t ) {
	var chart;
	var ctor;

	ctor = LineChart;
	chart = ctor();

	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (y)', function test( t ) {
	var chart;
	var ctor;

	ctor = LineChart;
	chart = ctor( [ 1, 2, 3 ] );

	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.strictEqual( chart.data.length, 1, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (options)', function test( t ) {
	var chart;
	var ctor;

	ctor = LineChart;
	chart = ctor({
		'lineWidth': 4
	});

	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.deepEqual( chart.lineWidth, [ 4 ], 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (x, y)', function test( t ) {
	var chart;
	var ctor;

	ctor = LineChart;
	chart = ctor( [ 1, 2, 3 ], [ 4, 5, 6 ] );

	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.strictEqual( chart.data.length, 1, 'returns expected value' );
	t.end();
});

tape( 'the constructor does not require the `new` keyword (x, y, options)', function test( t ) {
	var chart;
	var ctor;

	ctor = LineChart;
	chart = ctor( [ 1, 2, 3 ], [ 4, 5, 6 ], {
		'lineWidth': 4
	});

	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.strictEqual( chart.data.length, 1, 'returns expected value' );
	t.deepEqual( chart.lineWidth, [ 4 ], 'returns expected value' );
	t.end();
});

tape( 'the constructor supports providing x-values and y-values as ndarrays', function test( t ) {
	var chart;
	var x;
	var y;

	x = array( [ 1, 2, 3 ] );
	y = array( [ 4, 5, 6 ] );

	chart = new LineChart( x, y );
	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.strictEqual( chart.data.length, 1, 'returns expected value' );

	chart = new LineChart( y );
	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.strictEqual( chart.data.length, 1, 'returns expected value' );

	chart = new LineChart( x, y, {} );
	t.strictEqual( chart instanceof LineChart, true, 'returns class instance' );
	t.strictEqual( chart.data.length, 1, 'returns expected value' );

	t.end();
});

tape( 'the constructor supports providing an array of y-values (multiple datasets)', function test( t ) {
	var chart;
	var x;
	var y;

	x = [ 1, 2, 3 ];
	y = [
		[ 4, 5, 6 ],
		[ 7, 8, 9 ]
	];

	chart = new LineChart( x, y );
	t.strictEqual( chart.data.length, 2, 'returns expected value' );

	chart = new LineChart( x, y, {} );
	t.strictEqual( chart.data.length, 2, 'returns expected value' );

	chart = new LineChart( array( x ), [ array( y[ 0 ] ), array( y[ 1 ] ) ] );
	t.strictEqual( chart.data.length, 2, 'returns expected value' );

	chart = new LineChart( [ array( x ), array( x ) ], array( y[ 0 ] ) );
	t.strictEqual( chart.data.length, 2, 'returns expected value' );

	t.end();
});

tape( 'the constructor supports providing data and options', function test( t ) {
	var chart;

	chart = new LineChart( [ 4, 5, 6 ], {
		'lineStyle': '--'
	});
	t.strictEqual( chart.data.length, 1, 'returns expected value' );
	t.deepEqual( chart.lineStyle, [ '--' ], 'returns expected value' );

	chart = new LineChart( array( [ 4, 5, 6 ] ), {
		'lineStyle': '--'
	});
	t.strictEqual( chart.data.length, 1, 'returns expected value' );
	t.deepEqual( chart.lineStyle, [ '--' ], 'returns expected value' );

	t.end();
});

tape( 'positional data arguments take precedence over the `data` option', function test( t ) {
	var chart = new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], {
		'data': [ [ 1, 2 ], [ 3, 4 ], [ 5, 6 ] ]
	});
	t.strictEqual( chart.data.length, 1, 'returns expected value' );
	t.end();
});

tape( 'the constructor throws an error if provided an invalid first argument (one argument)', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws a type error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			new LineChart( value ); // eslint-disable-line no-new
		};
	}
});

