tape( 'the constructor throws an error if provided an array of y-values which is not an array of ndarrays when x-values are an ndarray', function test( t ) {
	t.throws( badValue, TypeError, 'throws a type error' );
	t.end();

	function badValue() {
		new LineChart( array( [ 1, 2, 3 ] ), [ [ 4, 5, 6 ] ] ); // eslint-disable-line no-new
	}
});

