tape( 'the constructor throws an error if provided an invalid option', function test( t ) {
	var values;
	var i;

	values = [
		{
			'colors': 5
		},
		{
			'legend': 'true'
		},
		{
			'lineOpacity': 2.0
		},
		{
			'lineStyle': 'beep'
		},
		{
			'lineSymbol': 5
		},
		{
			'lineWidth': '5'
		}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), Error, 'throws an error when provided '+JSON.stringify( values[i] ) );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			new LineChart( value ); // eslint-disable-line no-new
		};
	}
});

tape( 'the constructor sets default property values', function test( t ) {
	var chart = new LineChart();

	t.strictEqual( chart.colors.length > 0, true, 'returns expected value' );
	t.strictEqual( chart.legend, false, 'returns expected value' );
	t.deepEqual( chart.lineOpacity, [ 1.0 ], 'returns expected value' );
	t.deepEqual( chart.lineStyle, [ '-' ], 'returns expected value' );
	t.deepEqual( chart.lineSymbol, [ 'stroke' ], 'returns expected value' );
	t.deepEqual( chart.lineWidth, [ 2 ], 'returns expected value' );

	t.end();
});

tape( 'the constructor initializes internal encoding scales', function test( t ) {
	var chart = new LineChart();

	t.strictEqual( isObject( chart.colorScale ), true, 'returns expected value' );
	t.strictEqual( chart.colorScale.name, 'colorScale', 'returns expected value' );

	t.strictEqual( isObject( chart.lineOpacityScale ), true, 'returns expected value' );
	t.strictEqual( chart.lineOpacityScale.name, 'lineOpacityScale', 'returns expected value' );

	t.strictEqual( isObject( chart.lineStyleScale ), true, 'returns expected value' );
	t.strictEqual( chart.lineStyleScale.name, 'lineStyleScale', 'returns expected value' );

	t.strictEqual( isObject( chart.lineSymbolScale ), true, 'returns expected value' );
	t.strictEqual( chart.lineSymbolScale.name, 'lineSymbolScale', 'returns expected value' );

	t.strictEqual( isObject( chart.lineWidthScale ), true, 'returns expected value' );
	t.strictEqual( chart.lineWidthScale.name, 'lineWidthScale', 'returns expected value' );

	t.end();
});

tape( 'the scale properties are read-only', function test( t ) {
	var chart = new LineChart();

	t.throws( badValue( 'colorScale' ), Error, 'throws an error' );
	t.throws( badValue( 'lineOpacityScale' ), Error, 'throws an error' );
	t.throws( badValue( 'lineStyleScale' ), Error, 'throws an error' );
	t.throws( badValue( 'lineSymbolScale' ), Error, 'throws an error' );
	t.throws( badValue( 'lineWidthScale' ), Error, 'throws an error' );
	t.end();

	function badValue( prop ) {
		return function badValue() {
			chart[ prop ] = {};
		};
	}
});
